@extends('admin.layout') @section('title','استعلام‌ها') @section('heading','استعلام‌ها و CRM') @section('subheading','پیگیری سرنخ‌های فروش و وضعیت مذاکرات') @section('content')<div class="crm-board">@foreach(['new'=>'جدید','contacted'=>'تماس گرفته','quoted'=>'قیمت داده شد','won'=>'موفق','lost'=>'ناموفق'] as $status=>$label)<section class="crm-column"><header><span class="status-badge {{ $status }}">{{ $label }}</span><b>{{ fa_digits($quotes->where('status',$status)->count()) }}</b></header>@foreach($quotes->where('status',$status) as $q)<article><div><b>{{ $q->name }}</b><small>{{ $q->mobile }}</small></div><p>{{ $q->product_name ?: 'محصول مشخص نشده' }} · {{ $q->amount ? fa_digits($q->amount).' تن' : '—' }}</p><small>{{ $q->city }} · {{ jdate_fa($q->created_at,'Y/m/d H:i') }}</small><form method="post" action="{{ route('admin.quotes.update',$q) }}">@csrf @method('PUT')<select name="status">@foreach(['new'=>'جدید','contacted'=>'تماس گرفته','quoted'=>'قیمت داده شد','won'=>'موفق','lost'=>'ناموفق'] as $s=>$l)<option value="{{ $s }}" @selected($q->status===$s)>{{ $l }}</option>@endforeach</select><textarea name="note" placeholder="یادداشت پیگیری">{{ $q->note }}</textarea><button class="btn btn-outline btn-sm">ذخیره پیگیری</button></form></article>@endforeach</section>@endforeach</div>@endsection